static class Program {
 [DllImport("kernel32.dll")]static extern uint SetErrorMode(uint value);
 static int count;
 static void Check(bool c,string m){count++;if(!c)throw new InvalidOperationException(m);}
 [STAThread]static int Main(string[] args){SetErrorMode(0x8003);try{if(args.Contains("--verify-failure-exit"))throw new InvalidOperationException("Controlled standard-control test failure");Run();File.WriteAllText("analysis/full-audit/configuration-controls/checks.json",System.Text.Json.JsonSerializer.Serialize(new { checks=count,passed=true,boundary="Independent WPF/control-state verification; not original desktop pixel parity."}));Console.WriteLine($"{count} standard control checks passed; no original pixel-equivalence claim.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Run(){
  var xml="""<AlgorithmTabRoot><Tabs><Tab Name="Tab_Run Params"><Categorys><Category Name="Params"><Items><Integer Name="I"><AccessMode>RW</AccessMode><CurValue>5</CurValue><MinValue>0</MinValue><MaxValue>10</MaxValue><IncValue>3</IncValue></Integer><Float Name="F"><AccessMode>RW</AccessMode><CurValue>1.25</CurValue><MinValue>-10</MinValue><MaxValue>10</MaxValue><DecimalDigits>2</DecimalDigits><IncValue>0.1</IncValue></Float><Boolean Name="B"><AccessMode>RW</AccessMode><CurValue>False</CurValue></Boolean><Enumeration Name="E"><AccessMode>RW</AccessMode><CurValue>2</CurValue><EnumEntrys><EnumEntry><DisplayName>First</DisplayName><Value>1</Value></EnumEntry><EnumEntry><DisplayName>Second</DisplayName><Value>2</Value></EnumEntry></EnumEntrys></Enumeration><RadioSelecter Name="R"><AccessMode>RW</AccessMode><CurValue>1</CurValue><EnumEntrys><EnumEntry><DisplayName>First</DisplayName><Value>1</Value></EnumEntry><EnumEntry><DisplayName>Second</DisplayName><Value>2</Value></EnumEntry></EnumEntrys></RadioSelecter><StringConfig Name="Unsupported"/></Items></Category></Categorys></Tab></Tabs><BottomExcuteButtons><ExecuteOnceBottomCommand Name="Once"><DisplayName>Once</DisplayName><CommandSetter><ExcuteMethodOperation><MethodName>ExecuteOnce</MethodName></ExcuteMethodOperation></CommandSetter></ExecuteOnceBottomCommand><ContinuousExecuteBottomCommand Name="Continuous"/><StopExecuteBottomCommand Name="Stop"/><BottomCommand Name="Confirm"/></BottomExcuteButtons></AlgorithmTabRoot>""";
  var dispatcher=new Dispatcher();var state=new ToolConfigurationState(ToolConfigurationDefinition.Parse(xml),dispatcher);var registry=new ToolConfigurationControlRegistry();
  var execution=new ConfigurationExecutionVisualState(false,false,true);ToolConfigurationStandardControls.Register(registry,s=>"L:"+s,()=>execution);
  using var view=new ToolConfigurationView(state,registry);view.Measure(new Size(420,500));view.Arrange(new Rect(0,0,420,500));view.UpdateLayout();
  Directory.CreateDirectory("analysis/full-audit/configuration-controls");var bitmap=new RenderTargetBitmap(420,500,96,96,PixelFormats.Pbgra32);bitmap.Render(view);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create("analysis/full-audit/configuration-controls/standard-controls.png"))png.Save(stream);
  var spins=Walk(view).OfType<ConfigurationNumericSpinner>().ToArray();Check(spins.Length==2,"numeric controls must be dedicated spinners");
  var i=spins[0];Check(i.Height==32&&i.UpButton.Width==20&&i.UpButton.Height==15,"source numeric geometry");i.Step(1);Check(state.Find("I")!.Value=="6","integer step commits and native quantization");i.Step(1);Check(state.Find("I")!.Value=="9","integer second step");i.Step(-1);Check(state.Find("I")!.Value=="6","integer decrement");
  i.Editor.Text="NaN";Check(!i.CommitText()&&state.Find("I")!.Value=="6","reject NaN");i.Editor.Text="1.5";Check(!i.CommitText(),"integer rejects fraction");
  i.Editor.Text="11";Check(!i.CommitText()&&i.ValidationError!=null,"native typed range validation rejects rather than clamps");i.Editor.Text="";Check(i.CommitText()&&state.Find("I")!.Value=="0","native empty numeric means zero");
  var f=spins[1];f.Step(1);Check(state.Find("F")!.Value=="1.35","float step");Check(f.Editor.Text=="1.35","float digits retained");
  f.ConfigureSlider();Check(f.ValueSlider.Minimum==-10&&f.ValueSlider.Maximum==10&&f.ValueSlider.TickFrequency==.1,"slider native range and tick bindings");Check(f.ValueSlider.IsSnapToTickEnabled&&f.ValueSlider.TickPlacement==TickPlacement.BottomRight,"native slider snapping");Check(f.SliderPopup.Placement==PlacementMode.Bottom&&!f.SliderPopup.StaysOpen,"slider popup placement and dismissal");
  state.SetProgrammatic("I","CurValue","4");Check(i.Editor.Text=="3","programmatic refresh includes native quantization");state.SetProgrammatic("I","AccessMode","R");view.Refresh();Check(i.IsReadOnly,"readonly numeric");i.Step(1);Check(state.Find("I")!.Value=="3","readonly blocks step");
  var toggles=Walk(view).OfType<ToggleButton>().Where(x=>x is not RadioButton).ToArray();var toggle=toggles.First(t=>t.HorizontalAlignment==HorizontalAlignment.Left);toggle.IsChecked=true;toggle.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));Check(state.Find("B")!.Value=="True","switch commits");
  var combo=Walk(view).OfType<ComboBox>().Single();Check(combo.Height==30&&combo.Items.Count==2,"original enum type and height");combo.SelectedValue="1";Check(state.Find("E")!.Value=="1","selector commits");
  var radio=Walk(view).OfType<RadioButton>().ToArray();Check(radio.Length==2&&radio[0].Height==32,"native two radio choices");radio[1].IsChecked=true;Check(state.Find("R")!.Value=="2","radio commits");
  var commands=Walk(view).OfType<Button>().Where(b=>b.Content is string s&&s.StartsWith("L:")).ToArray();var once=commands.Single(b=>(string)b.Content=="L:Once");var stop=commands.Single(b=>(string)b.Content=="L:Stop");
  Check(once.Visibility==Visibility.Visible&&stop.Visibility==Visibility.Collapsed,"initial command state");Check(once.Height==24&&once.MinWidth==66,"source footer dimensions");
  execution=new(true,false,true);view.Refresh();Check(once.Visibility==Visibility.Collapsed&&stop.Visibility==Visibility.Visible,"continuous-stop mutual visibility");execution=new(false,true,true);view.Refresh();Check(!once.IsEnabled,"procedure running blocks run");execution=new(false,false,false);view.Refresh();Check(once.Visibility==Visibility.Collapsed,"run disabled hides run");
  state.SetProgrammatic("I","IsSub","True");Check(i.Visibility==Visibility.Collapsed,"subscription never masquerades as numeric");Check(Walk(view).OfType<TextBlock>().Any(t=>t.Tag is ConfigurationControlLimitation),"explicit subscription limitation");
  Check(view.Diagnostics.Any(d=>d.TemplateKey=="StringConfig"),"complex control unregistered");
  var subscribedState=new ToolConfigurationState(ToolConfigurationDefinition.Parse(xml),dispatcher);var subscribedRegistry=new ToolConfigurationControlRegistry();var service=new SubscriptionService();ToolConfigurationStandardControls.Register(subscribedRegistry,subscriptions:service);
  using var subscribedView=new ToolConfigurationView(subscribedState,subscribedRegistry);subscribedView.Measure(new Size(420,500));subscribedView.Arrange(new Rect(0,0,420,500));subscribedView.UpdateLayout();
  var selectors=Walk(subscribedView).OfType<ToolConfigurationSubscriptionSelector>().ToArray();Check(selectors.Length==2,"numeric typed subscription leaves embedded");Check(service.Reads==2,"typed authoritative read per numeric");
  var mode=Walk(subscribedView).OfType<ToggleButton>().First(t=>t.Width==26);Check(mode.Height==26&&mode.IsEnabled,"source numeric edit-link switch");
  mode.IsChecked=true;mode.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));Check(subscribedState.Find("I")!.Get("IsSub")=="True"&&subscribedState.Find("I")!.SubscriptionBinding==null,"unbound subscribed mode retained");Check(selectors[0].Visibility==Visibility.Visible,"mode switch exposes typed selector");Check(selectors[0].SetMode(false),"unbound edit mode restoration");
  Check(selectors[0].Bind(new ConfigurationSubscriptionBinding(new ConfigurationGlobalReference("global-id","int"),ConfigurationSubscriptionIndex.All)),"typed numeric binding");Check(subscribedState.Find("I")!.SubscriptionBinding?.Reference is ConfigurationGlobalReference g&&g.VariableId=="global-id","reference identity retained");
  Check(Walk(subscribedView).OfType<ConfigurationNumericSpinner>().First().Visibility==Visibility.Collapsed,"typed subscribed mode hides numeric");Check(selectors[0].SetMode(false),"clear binding returns numeric mode");Check(Walk(subscribedView).OfType<ConfigurationNumericSpinner>().First().Visibility==Visibility.Visible,"numeric restored after clear");
  var extraDefinition=ToolConfigurationDefinition.Parse("<AlgorithmTabRoot><Tabs><Tab Name='Tab_Run Params'><Categorys><Category Name='Extra'><Items><String Name='Text'><AccessMode>RW</AccessMode><CurValue>old</CurValue><Length>4</Length><MaxLen>6</MaxLen><SubscribeVisible>False</SubscribeVisible></String><Command Name='Action'><DisplayName>Action</DisplayName><CommandSetter><OperationName>ExcuteMethodOperation</OperationName><OperationParams>SelfExcuteModule</OperationParams></CommandSetter></Command><Expand><CurValue>False</CurValue></Expand></Items></Category></Categorys></Tab></Tabs><BottomExcuteButtonsLeft><Button_ResetAlgoParams Name='Reset'/></BottomExcuteButtonsLeft></AlgorithmTabRoot>");
  var extraDispatch=new Dispatcher();var extraState=new ToolConfigurationState(extraDefinition,extraDispatch);var extraRegistry=new ToolConfigurationControlRegistry();ToolConfigurationStandardControls.Register(extraRegistry);
  using var extraView=new ToolConfigurationView(extraState,extraRegistry);extraView.Measure(new Size(420,500));extraView.Arrange(new Rect(0,0,420,500));extraView.UpdateLayout();Check(extraView.Diagnostics.Count==0,"String Command Expand Reset use actual standard factories");
  var input=Walk(extraView).OfType<TextBox>().Single();Check(input.MaxLength==4&&input.FontSize==14,"native String Length bound separately from MaxLen");input.Text="中文";input.RaiseEvent(new RoutedEventArgs(UIElement.LostFocusEvent));Check(extraState.Find("Text")!.Value=="中文","String commits on source LostFocus");input.Text="中文长";input.RaiseEvent(new RoutedEventArgs(UIElement.LostFocusEvent));Check(extraState.Find("Text")!.Value=="中文"&&extraState.Diagnostics.Any(d=>d.Code=="InvalidValue"),"native UTF8 byte MaxLen rejects long text");
  var expand=Walk(extraView).OfType<ToggleButton>().Single(t=>t.Height==30);int writesBefore=extraDispatch.Requests.Count;expand.IsChecked=true;expand.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));Check(extraState.Nodes.Single(n=>n.Element.Tag=="Expand").Value=="True"&&extraDispatch.Requests.Count==writesBefore,"Expand is model-only without native write/run");
  var action=Walk(extraView).OfType<Button>().Single(b=>b.Content as string=="Action");Check(action.Height==24&&action.Padding==new Thickness(4,0,4,0),"native Command inline button geometry");action.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));Check(extraDispatch.Requests.Last().Kind==ConfigurationOperationKind.Run,"Command invokes explicit source operation");
  var reset=Walk(extraView).OfType<Button>().Single(b=>b.Style?.TargetType==typeof(Button)&&b.Content==null);reset.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));Check(extraDispatch.Requests.Last().Kind==ConfigurationOperationKind.ResetParameters,"Reset goes through state command service");
  var resource=new ResourceDictionary{Source=new Uri("/VisionPluginContracts;component/Resources/ConfigurationControls.xaml",UriKind.Relative)};foreach(var key in new[]{"ConfigurationSwitch","ConfigurationNumericArrow","ConfigurationRadio","ConfigurationBottomButton","ConfigurationEnumeration"})Check(resource[key] is Style,"style "+key);
 }
 static IEnumerable<DependencyObject> Walk(DependencyObject root){yield return root;for(int n=0;n<VisualTreeHelper.GetChildrenCount(root);n++)foreach(var v in Walk(VisualTreeHelper.GetChild(root,n)))yield return v;}
 sealed class SubscriptionService:IToolConfigurationSubscriptionService {
  public int Reads;ConfigurationSubscriptionBinding? binding;
  public ConfigurationSubscriptionTreeResult Enumerate(ConfigurationSubscriptionQuery q)=>new(ConfigurationSubscriptionStatus.Available,Array.Empty<ConfigurationSubscriptionTreeNode>());
  public ConfigurationSubscriptionBindingResult Read(ConfigurationSubscriptionDestination d){Reads++;return new(ConfigurationSubscriptionStatus.Available,binding,binding==null?"":"Service caption");}
  public ConfigurationSubscriptionBindingResult Bind(ConfigurationSubscriptionDestination d,ConfigurationSubscriptionBinding? b){binding=b;return new(ConfigurationSubscriptionStatus.Available,b,b==null?"":"Service caption");}
 }
 sealed class Dispatcher:IToolConfigurationDispatcher{public List<ConfigurationOperationRequest> Requests{get;}=[];public ConfigurationOperationResult Dispatch(ConfigurationOperationRequest r){Requests.Add(r);return new(true,r.Kind==ConfigurationOperationKind.ReadParameter?r.Source.Value:null);}}
}
